lessons.viewSource:
view diagram "01 / Whiteboard sketch" {
    data: [@s.model];
    format: @fmt.shared.technical;
    style: @fmt.shared.sketch;
    layout: @fmt.shared.row;
    select: [@s.model.customer, @s.model.order, @s.model.shipment];
    publication { width: 1580px; height: 440px; }
    legend { keys: { "model.r_a": 1, "model.r_b": 2 }; }
}

view diagram "02 / Business concepts" {
    data: [@c.concepts];
    format: @fmt.shared.technical;
    style: @fmt.shared.classic;
    layout: @fmt.shared.row;
    select: [@c.concepts.customer, @c.concepts.order, @c.concepts.shipment];
    publication { width: 1580px; height: 440px; }
    legend { keys: { "concepts.r_places": 1, "concepts.r_ships": 2 }; }
}

view collaboration "Buyer / seller collaboration" {
    data: [@quote]; format: @shared.styles.technical;
    projection { kind: graph; profile: "bpmn.basic@1"; }
    layout { algorithm: layered; }
    publication { size: content; fit: none; overflow: error; minimum_text: 8pt; }
    frame buyer "Buyer" { x_pool: true; members: [@quote.start, @quote.request_quote, @quote.decide, @quote.failed]; }
    frame seller "Seller" { x_pool: true; members: [@quote.receive, @quote.prepare_quote, @quote.sent]; }
}

view latency_chart "Latency / chart" {
    data: [@metrics];
    projection { kind: chart; profile: "chart.basic@1"; records: [@metrics.m1, @metrics.m2, @metrics.m3]; mark: bar; x: "x_record.label"; y: "x_record.value"; unit: "ms"; width: 900px; height: 560px; }
    publication { size: content; fit: none; }
}

view d "Motor control ladder" {
    data: [@rung1, @rung2, @rung3];
    projection { profile: "ladder.basic@1"; }
    layout { algorithm: ladder; }
    publication { size: content; fit: none; }
}

view decision_first "14 / Disposition policy — first" {
    data: [@m.rules];
    format: @f.shared.common;
    projection { kind: "decision"; profile: "decision.rules@1"; records: [@m.rules.high, @m.rules.default, @m.rules.low_pass]; inputs: [{ "key": "severity", "type": "enum", "values": ["low", "high"] }, { "key": "score", "type": "number", "min": 0, "max": 10 }]; outputs: ["route", "audit"]; hit_policy: "first"; coverage: "complete"; analysis_budget: 4096; }
    select: [@m.rules.high, @m.rules.default, @m.rules.low_pass];

}
